#!/usr/bin/env node
// Regenerates packages/crosswalk/src/oscal-index.ts — a slim, vendored index of
// the NIST SP 800-53 Rev 5 control catalog (id, title, family, withdrawn flag)
// derived from a PINNED usnistgov/oscal-content release. The generated file is
// checked in and consumed offline by the integrity suite; nothing fetches at
// test/build/runtime. Re-running against the same pin is byte-identical.
//
//   node scripts/refresh-oscal.mjs
//
// Bump OSCAL_TAG to adopt a newer catalog, then re-run and review the diff.

import { writeFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const OSCAL_TAG = "v1.5.0";
const SOURCE_URL = `https://raw.githubusercontent.com/usnistgov/oscal-content/${OSCAL_TAG}/nist.gov/SP800-53/rev5/json/NIST_SP-800-53_rev5_catalog.json`;
const RETRIEVED = "2026-07-11"; // date this vendored index was generated

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = resolve(root, "packages/crosswalk/src/oscal-index.ts");

const labelOf = (ctrl) => {
  // The unclassed "label" prop is the canonical display id (e.g. "AC-1", "SA-12").
  const p = (ctrl.props || []).find((x) => x.name === "label" && !x.class);
  return p ? p.value : ctrl.id.toUpperCase();
};
const isWithdrawn = (ctrl) =>
  (ctrl.props || []).some((p) => p.name === "status" && p.value === "withdrawn");

const res = await fetch(SOURCE_URL);
if (!res.ok) throw new Error(`fetch ${SOURCE_URL} -> ${res.status}`);
const catalog = (await res.json()).catalog;

const index = {};
for (const group of catalog.groups) {
  const family = group.id.toUpperCase();
  for (const ctrl of group.controls || []) {
    // Base controls only — the crosswalk references base controls, not enhancements.
    index[labelOf(ctrl)] = { title: ctrl.title, family, withdrawn: isWithdrawn(ctrl) };
  }
}

const sorted = Object.keys(index).sort((a, b) => {
  const [af, an] = a.split("-");
  const [bf, bn] = b.split("-");
  return af === bf ? Number(an) - Number(bn) : af.localeCompare(bf);
});

const body = sorted
  .map((id) => {
    const e = index[id];
    return `  ${JSON.stringify(id)}: { title: ${JSON.stringify(e.title)}, family: ${JSON.stringify(e.family)}, withdrawn: ${e.withdrawn} },`;
  })
  .join("\n");

const out = `// GENERATED by scripts/refresh-oscal.mjs — DO NOT EDIT BY HAND.
// Source: usnistgov/oscal-content ${OSCAL_TAG} (NIST SP 800-53 Rev 5 catalog)
//   ${SOURCE_URL}
// Retrieved: ${RETRIEVED}
// A slim, offline index of base controls: display id -> { title, family, withdrawn }.

export interface OscalControl {
  title: string;
  family: string;
  withdrawn: boolean;
}

export const OSCAL_SOURCE = {
  tag: ${JSON.stringify(OSCAL_TAG)},
  url: ${JSON.stringify(SOURCE_URL)},
  retrieved: ${JSON.stringify(RETRIEVED)},
} as const;

export const OSCAL_800_53_REV5: Record<string, OscalControl> = {
${body}
};
`;

writeFileSync(OUT, out);
console.log(`Wrote ${OUT}: ${sorted.length} base controls (${sorted.filter((id) => index[id].withdrawn).length} withdrawn).`);
